42	+
43	+namespace {
44	+
45	+constexpr int OP_ADD = 0;
46	+constexpr int OP_REMOVE = 1;
47	+constexpr int SIDE_BID = 0;
48	+constexpr int SIDE_ASK = 1;
49	+
50	+// Level oracle: the flat book's per-side level arrays and best scan, isolated
51	+// from order tracking (which stays in software / out of hardware scope).
52	+struct LevelBook {
53	+    std::vector<uint32_t> bid, ask;
54	+    explicit LevelBook(std::size_t depth) : bid(depth, 0), ask(depth, 0) {}
55	+
56	+    // Returns true only on a true underflow — a REMOVE for MORE shares than the
57	+    // level holds — which clamps to zero (the phantom-depth rule). Exact
58	+    // removal (shares == level) empties the level without an underflow, matching
59	+    // OrderBookFlat::_remove_level's `if (lv <= shares) lv = 0;` for the value
60	+    // while distinguishing the error pulse from a clean emptying.
61	+    bool apply(int op, int side, std::size_t idx, uint32_t shares) {
62	+        std::vector<uint32_t>& lv = (side == SIDE_BID) ? bid : ask;
63	+        if (op == OP_ADD) {
64	+            lv[idx] += shares;
65	+            return false;
66	+        }
67	+        if (shares > lv[idx]) {
68	+            lv[idx] = 0;
69	+            return true;  // underflow clamp
70	+        }
71	+        lv[idx] -= shares;
72	+        return false;
73	+    }
74	+
75	+    // best_bid: highest occupied index; best_ask: lowest occupied index.
76	+    bool best(int side, std::size_t& idx, uint32_t& shares) const {
77	+        const std::vector<uint32_t>& lv = (side == SIDE_BID) ? bid : ask;
78	+        if (side == SIDE_BID) {
79	+            for (std::size_t i = lv.size(); i-- > 0;)
80	+                if (lv[i] > 0) { idx = i; shares = lv[i]; return true; }
81	+        } else {
82	+            for (std::size_t i = 0; i < lv.size(); ++i)
83	+                if (lv[i] > 0) { idx = i; shares = lv[i]; return true; }
84	+        }
85	+        idx = 0;
86	+        shares = 0;
87	+        return false;
88	+    }
89	+};
90	+
91	+struct Op {
92	+    int op, side;
93	+    uint32_t index, shares;
94	+};
95	+
96	+void write_csv(std::FILE* out, std::size_t depth, const std::vector<Op>& ops) {
97	+    std::fprintf(out, "# flat_book_golden schema=1 depth=%zu shares_w=32\n", depth);
98	+    std::fprintf(out,
99	+        "op,side,index,shares,bid_valid,bid_index,bid_shares,"
100	+        "ask_valid,ask_index,ask_shares,clamp\n");
101	+    LevelBook book(depth);
102	+    for (const Op& o : ops) {
103	+        const bool clamp = book.apply(o.op, o.side, o.index, o.shares);
104	+        std::size_t bidx = 0, aidx = 0;
105	+        uint32_t bsh = 0, ash = 0;
106	+        const bool bv = book.best(SIDE_BID, bidx, bsh);
107	+        const bool av = book.best(SIDE_ASK, aidx, ash);
108	+        std::fprintf(out, "%d,%d,%u,%u,%d,%zu,%u,%d,%zu,%u,%d\n",
109	+                     o.op, o.side, o.index, o.shares,
110	+                     bv ? 1 : 0, bidx, bsh, av ? 1 : 0, aidx, ash, clamp ? 1 : 0);
111	+    }
112	+}
113	+
114	+// Hand-written sequence hitting the contract's corners: boundary indexes 0 and
115	+// depth-1, clamp-at-zero, removing the current best (best moves), and emptying
116	+// a side (best_valid deasserts).
117	+std::vector<Op> edge_ops(std::size_t depth) {
118	+    const uint32_t hi = static_cast<uint32_t>(depth - 1);
119	+    return {
120	+        {OP_ADD, SIDE_BID, 100, 500},        // bid best = 100
121	+        {OP_ADD, SIDE_BID, 200, 300},        // bid best moves up to 200
122	+        {OP_ADD, SIDE_BID, 0, 111},          // boundary index 0 (not best)
123	+        {OP_ADD, SIDE_ASK, 400, 250},        // ask best = 400
124	+        {OP_ADD, SIDE_ASK, hi, 999},         // boundary index depth-1
125	+        {OP_ADD, SIDE_ASK, 350, 700},        // ask best moves down to 350
126	+        {OP_REMOVE, SIDE_ASK, 350, 700},     // remove best ask -> back to 400
127	+        {OP_REMOVE, SIDE_BID, 200, 1000},    // over-remove best bid -> clamp, best back to 100
128	+        {OP_REMOVE, SIDE_BID, 100, 500},     // empty 100
129	+        {OP_REMOVE, SIDE_BID, 0, 111},       // empty side -> bid best invalid
130	+        {OP_REMOVE, SIDE_ASK, 400, 250},     // empty 400 -> ask best = depth-1
131	+        {OP_REMOVE, SIDE_ASK, hi, 999},      // empty side -> ask best invalid
132	+    };
133	+}
134	+
135	+std::vector<Op> random_ops(std::size_t depth, uint32_t seed, int n) {
136	+    std::mt19937 rng(seed);
137	+    std::uniform_int_distribution<int> side(0, 1);
138	+    std::uniform_int_distribution<int> op(0, 1);
139	+    std::uniform_int_distribution<uint32_t> idx(0, static_cast<uint32_t>(depth - 1));
140	+    std::uniform_int_distribution<uint32_t> sh(1, 1000);
141	+    std::vector<Op> ops;
142	+    ops.reserve(n);
143	+    for (int i = 0; i < n; ++i)
144	+        ops.push_back({op(rng), side(rng), idx(rng), sh(rng)});
145	+    return ops;
146	+}
147	+
148	+}  // namespace
