156	-    return 2;
157	+    if (argc < 4) {
158	+        std::fprintf(stderr,
159	+            "usage: %s <edge|random> <depth> <out.csv> [seed]\n", argv[0]);
160	+        return 2;
161	+    }
162	+    const std::string mode = argv[1];
163	+    const std::size_t depth = std::strtoul(argv[2], nullptr, 10);
164	+    const char* out_path = argv[3];
165	+    const uint32_t seed = argc >= 5 ? std::strtoul(argv[4], nullptr, 10) : 12345u;
166	+    if (depth < 2 || depth > 4096) {
167	+        std::fprintf(stderr, "depth must be in [2, 4096]\n");
168	+        return 2;
169	+    }
170	+
171	+    std::vector<Op> ops;
172	+    if (mode == "edge") {
173	+        ops = edge_ops(depth);
174	+    } else if (mode == "random") {
175	+        ops = random_ops(depth, seed, 10000);
176	+    } else {
177	+        std::fprintf(stderr, "unknown mode '%s' (edge|random)\n", mode.c_str());
178	+        return 2;
179	+    }
180	+
181	+    std::FILE* out = std::fopen(out_path, "wb");
182	+    if (!out) {
183	+        std::fprintf(stderr, "cannot open %s for writing\n", out_path);
184	+        return 2;
185	+    }
186	+    write_csv(out, depth, ops);
187	+    std::fclose(out);
188	+    std::fprintf(stderr, "wrote %zu ops (%s, depth=%zu) to %s\n",
189	+                 ops.size(), mode.c_str(), depth, out_path);
190	+    return 0;
191	 }
