230	 architecture rtl of flat_book is
231	-  -- TODO(vhdl-2): two level arrays (BRAM-style), per-side occupancy
232	-  -- bitmask; TODO(vhdl-3): priority encoders.
233	+  subtype share_t is unsigned(SHARES_W - 1 downto 0);
234	+  type level_array is array(0 to DEPTH - 1) of share_t;
235	+  constant ZERO_SHARES : share_t := (others => '0');
236	 begin
237	-  -- TODO(vhdl-2): implement. Scaffold ties outputs inactive so the file
238	-  -- analyzes cleanly under `ghdl -a` before implementation begins.
239	-  best_bid_valid  <= '0';
240	-  best_bid_index  <= (others => '0');
241	-  best_bid_shares <= (others => '0');
242	-  best_ask_valid  <= '0';
243	-  best_ask_index  <= (others => '0');
244	-  best_ask_shares <= (others => '0');
245	-  err_underflow_clamped <= '0';
246	+  -- Single clocked process. The level arrays are process VARIABLES so an
247	+  -- update is visible to the best-scan in the same cycle; the outputs are
248	+  -- registered signal drives, valid immediately after the clock edge.
249	+  process(clk)
250	+    variable bid_lv : level_array := (others => (others => '0'));
251	+    variable ask_lv : level_array := (others => (others => '0'));
252	+    variable idx    : integer range 0 to DEPTH - 1;
253	+    variable clamp  : std_logic;
254	+    variable found  : boolean;
255	+  begin
256	+    if rising_edge(clk) then
257	+      clamp := '0';
258	+      if rst = '1' then
259	+        bid_lv := (others => (others => '0'));
260	+        ask_lv := (others => (others => '0'));
261	+      elsif op_valid = '1' then
262	+        idx := to_integer(op_index);
263	+        if op_side = '0' then                    -- BID
264	+          if op_kind = '0' then                  -- ADD
265	+            bid_lv(idx) := bid_lv(idx) + op_shares;
266	+          elsif op_shares > bid_lv(idx) then      -- REMOVE underflow
267	+            bid_lv(idx) := (others => '0');
268	+            clamp := '1';
269	+          else
270	+            bid_lv(idx) := bid_lv(idx) - op_shares;
271	+          end if;
272	+        else                                     -- ASK
273	+          if op_kind = '0' then
274	+            ask_lv(idx) := ask_lv(idx) + op_shares;
275	+          elsif op_shares > ask_lv(idx) then
276	+            ask_lv(idx) := (others => '0');
277	+            clamp := '1';
278	+          else
279	+            ask_lv(idx) := ask_lv(idx) - op_shares;
280	+          end if;
281	+        end if;
282	+      end if;
283	+      err_underflow_clamped <= clamp;
284	+
285	+      -- Best bid: highest occupied index (priority encoder, high-to-low).
286	+      found := false;
287	+      for i in DEPTH - 1 downto 0 loop
288	+        if not found and bid_lv(i) /= ZERO_SHARES then
289	+          best_bid_valid  <= '1';
290	+          best_bid_index  <= to_unsigned(i, 12);
291	+          best_bid_shares <= bid_lv(i);
292	+          found := true;
293	+        end if;
294	+      end loop;
295	+      if not found then
296	+        best_bid_valid  <= '0';
297	+        best_bid_index  <= (others => '0');
298	+        best_bid_shares <= (others => '0');
299	+      end if;
300	+
301	+      -- Best ask: lowest occupied index (priority encoder, low-to-high).
302	+      found := false;
303	+      for i in 0 to DEPTH - 1 loop
304	+        if not found and ask_lv(i) /= ZERO_SHARES then
305	+          best_ask_valid  <= '1';
306	+          best_ask_index  <= to_unsigned(i, 12);
307	+          best_ask_shares <= ask_lv(i);
308	+          found := true;
309	+        end if;
310	+      end loop;
311	+      if not found then
312	+        best_ask_valid  <= '0';
313	+        best_ask_index  <= (others => '0');
314	+        best_ask_shares <= (others => '0');
315	+      end if;
316	+    end if;
317	+  end process;
