1	#pragma once
2	#include "order_book.hpp"  // re-uses OrderRecord, PriceLevel, TopOfBook
3	#include <cstdint>
4	#include <unordered_map>
5	#include <vector>
6	#include <stdexcept>
7	#include <algorithm>
8	
9	// Optimised order book: price levels stored in a flat contiguous array
10	// indexed by (price_raw - min_price_raw) / tick_size.
11	//
12	// This replaces the hash-map baseline's std::map<price, shares> with a
13	// vector<uint32_t> where index == price tick.  The tradeoffs are:
14	//   + O(1) level lookup and update (vs O(log n) for std::map).
15	//   + Sequential memory layout — best-bid/ask scan is a cache-friendly
16	//     linear sweep over a small array.
17	//   - Fixed price range: [min_price_raw, max_price_raw] must be declared
18	//     at construction.  Out-of-range prices increment error_count.
19	//
20	// The public interface is identical to OrderBook so the bench driver needs
21	// no changes — just swap the type.
22	
23	namespace itch {
24	
25	class OrderBookFlat {
26	public:
27	    // min_price_raw / max_price_raw: inclusive bounds of the instrument's
28	    // expected tick range (in ITCH fixed-point units, i.e. price * 10000).
29	    // tick_size: granularity (default 1 = minimum ITCH resolution).
30	    //
31	    // Example for a stock trading $90–$110 with 0.0001 resolution:
32	    //   OrderBookFlat book(900000, 1100000, 1);
33	    OrderBookFlat(uint32_t min_price_raw, uint32_t max_price_raw, uint32_t tick_size = 1)
34	        : min_price_(min_price_raw)
35	        , max_price_(max_price_raw)
36	        , tick_size_(tick_size)
37	    {
38	        if (max_price_raw <= min_price_raw)
39	            throw std::invalid_argument("max_price_raw must be > min_price_raw");
40	        if (tick_size == 0)
41	            throw std::invalid_argument("tick_size must be > 0");
42	        const std::size_t n = (max_price_raw - min_price_raw) / tick_size + 1;
43	        bid_levels_.assign(n, 0);
44	        ask_levels_.assign(n, 0);
45	    }
46	
47	    void add(uint64_t order_ref, char side, uint32_t price_raw, uint32_t shares) {
48	        if (orders_.count(order_ref)) { ++error_count_; return; }
49	        const std::size_t idx = _index(price_raw);
50	        if (idx == INVALID) { ++error_count_; return; }
51	        orders_[order_ref] = {side, price_raw, shares};
52	        _levels(side)[idx] += shares;
53	    }
54	
55	    uint32_t execute(uint64_t order_ref, uint32_t executed_shares) {
56	        auto it = orders_.find(order_ref);
57	        if (it == orders_.end()) { ++error_count_; return 0; }
58	        OrderRecord& rec = it->second;
59	        const uint32_t to_remove = std::min(executed_shares, rec.shares);
60	        _remove_level(rec.side, rec.price_raw, to_remove);
61	        rec.shares -= to_remove;
62	        if (rec.shares == 0) orders_.erase(it);
63	        return to_remove;
64	    }
65	
66	    bool del(uint64_t order_ref) {
67	        auto it = orders_.find(order_ref);
68	        if (it == orders_.end()) { ++error_count_; return false; }
69	        const OrderRecord& rec = it->second;
70	        _remove_level(rec.side, rec.price_raw, rec.shares);
71	        orders_.erase(it);
72	        return true;
73	    }
74	
75	    void replace(uint64_t old_ref, uint64_t new_ref, uint32_t shares, uint32_t price_raw) {
76	        auto it = orders_.find(old_ref);
77	        if (it == orders_.end()) { ++error_count_; return; }
78	        const char side = it->second.side;
79	        _remove_level(side, it->second.price_raw, it->second.shares);
80	        orders_.erase(it);
81	        add(new_ref, side, price_raw, shares);
82	    }
83	
84	    TopOfBook top_of_book() const {
85	        TopOfBook tob;
86	        // Best bid: highest price index with non-zero shares.
87	        for (std::size_t i = bid_levels_.size(); i-- > 0;) {
88	            if (bid_levels_[i] > 0) {
89	                tob.best_bid = PriceLevel{
90	                    min_price_ + static_cast<uint32_t>(i) * tick_size_,
91	                    bid_levels_[i]
92	                };
93	                break;
94	            }
95	        }
96	        // Best ask: lowest price index with non-zero shares.
97	        for (std::size_t i = 0; i < ask_levels_.size(); ++i) {
98	            if (ask_levels_[i] > 0) {
99	                tob.best_ask = PriceLevel{
100	                    min_price_ + static_cast<uint32_t>(i) * tick_size_,
101	                    ask_levels_[i]
102	                };
103	                break;
104	            }
105	        }
106	        return tob;
107	    }
108	
109	    uint64_t error_count() const { return error_count_; }
110	    std::size_t order_count() const { return orders_.size(); }
111	
112	private:
113	    static constexpr std::size_t INVALID = SIZE_MAX;
