1	// Golden-vector generator for the VHDL flat book.
2	// Plan: .claude/plans/vhdl-flat-book.md, step 1.
3	//
4	// Emits a CSV of price-LEVEL operations (op, side, tick_index, shares) each
5	// followed by the expected best-of-book outputs and clamp flag, for the VHDL
6	// testbench to replay and assert against. The oracle here implements exactly
7	// the level-update rule of cpp/itch/order_book_flat.hpp — ADD accumulates,
8	// REMOVE clamps at zero (the phantom-depth rule from _remove_level) — and the
9	// best-of-book scan directions (bid from the HIGH index, ask from the LOW).
10	//
11	// Usage: golden_vectors <edge|random> <depth> <out.csv> [seed]
12	//   edge   : hand-written boundary / clamp / emptying sequence
13	//   random : seeded pseudo-random ~10k-op sequence (determinism via the seed)
14	//
15	// The CSV's first line is a schema+params comment the testbench asserts before
16	// running, so a format drift fails loudly rather than mis-parsing.
17	
18	#include <cstdint>
19	#include <cstdio>
20	#include <cstdlib>
21	#include <random>
22	#include <string>
23	#include <vector>
24	
25	namespace {
26	
27	constexpr int OP_ADD = 0;
28	constexpr int OP_REMOVE = 1;
29	constexpr int SIDE_BID = 0;
30	constexpr int SIDE_ASK = 1;
31	
32	// Level oracle: the flat book's per-side level arrays and best scan, isolated
33	// from order tracking (which stays in software / out of hardware scope).
34	struct LevelBook {
35	    std::vector<uint32_t> bid, ask;
36	    explicit LevelBook(std::size_t depth) : bid(depth, 0), ask(depth, 0) {}
37	
38	    // Returns true only on a true underflow — a REMOVE for MORE shares than the
39	    // level holds — which clamps to zero (the phantom-depth rule). Exact
40	    // removal (shares == level) empties the level without an underflow, matching
41	    // OrderBookFlat::_remove_level's `if (lv <= shares) lv = 0;` for the value
42	    // while distinguishing the error pulse from a clean emptying.
43	    bool apply(int op, int side, std::size_t idx, uint32_t shares) {
44	        std::vector<uint32_t>& lv = (side == SIDE_BID) ? bid : ask;
45	        if (op == OP_ADD) {
46	            lv[idx] += shares;
47	            return false;
48	        }
49	        if (shares > lv[idx]) {
50	            lv[idx] = 0;
51	            return true;  // underflow clamp
52	        }
53	        lv[idx] -= shares;
54	        return false;
55	    }
56	
57	    // best_bid: highest occupied index; best_ask: lowest occupied index.
58	    bool best(int side, std::size_t& idx, uint32_t& shares) const {
59	        const std::vector<uint32_t>& lv = (side == SIDE_BID) ? bid : ask;
60	        if (side == SIDE_BID) {
61	            for (std::size_t i = lv.size(); i-- > 0;)
62	                if (lv[i] > 0) { idx = i; shares = lv[i]; return true; }
63	        } else {
64	            for (std::size_t i = 0; i < lv.size(); ++i)
65	                if (lv[i] > 0) { idx = i; shares = lv[i]; return true; }
66	        }
67	        idx = 0;
68	        shares = 0;
69	        return false;
70	    }
71	};
72	
73	struct Op {
74	    int op, side;
75	    uint32_t index, shares;
76	};
77	
78	void write_csv(std::FILE* out, std::size_t depth, const std::vector<Op>& ops) {
79	    std::fprintf(out, "# flat_book_golden schema=1 depth=%zu shares_w=32\n", depth);
80	    std::fprintf(out,
81	        "op,side,index,shares,bid_valid,bid_index,bid_shares,"
82	        "ask_valid,ask_index,ask_shares,clamp\n");
83	    LevelBook book(depth);
84	    for (const Op& o : ops) {
85	        const bool clamp = book.apply(o.op, o.side, o.index, o.shares);
86	        std::size_t bidx = 0, aidx = 0;
87	        uint32_t bsh = 0, ash = 0;
88	        const bool bv = book.best(SIDE_BID, bidx, bsh);
89	        const bool av = book.best(SIDE_ASK, aidx, ash);
